-- All records below are fictional and exist only in the disposable test DB.
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000000001','owner@example.invalid'),('00000000-0000-0000-0000-000000000002','cashier@example.invalid'),('00000000-0000-0000-0000-000000000003','outsider@example.invalid');
insert into public.app_users(email,role) values('owner@example.invalid','dueno'),('cashier@example.invalid','cajero');
insert into public.public_catalog_products(id,publishable,data) values('fixture-product',true,'{"id":"fixture-product","name":"Fixture","publishable":true,"variants":[{"id":"fixture-variant","sku":"FIXTURE-1","stock":10,"price":100,"cost":25}]}');
insert into public.operational_state(id,data) select 'main',jsonb_build_object('products','[]'::jsonb,'sales','[{"id":"sale-existing","total":100,"payments":[]}]'::jsonb,'quotes','[]'::jsonb,'transfers','[]'::jsonb,'expenses','[]'::jsonb,'movements','[]'::jsonb,'onlineOrders','[]'::jsonb,'purchaseReceipts','[]'::jsonb,'customers','[]'::jsonb,'suppliers','[]'::jsonb,'cashClosures','[]'::jsonb,'cashShifts','[]'::jsonb,'supplierPayments','[]'::jsonb,'capitalEntries','[{"id":"capital-existing","amount":2400}]'::jsonb,'emailMessages','[]'::jsonb,'salesAuditEntries','[]'::jsonb,'operationAuditEntries','[]'::jsonb,'businessProfile','{}'::jsonb,'categories','[]'::jsonb,'rolePermissions','{}'::jsonb,'updatedAt',now());
create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'ASSERT: %',message;end if;end$$;
create function pg_temp.assert_error(command text,expected text) returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=expected then return;else raise exception 'Wrong SQLSTATE %, expected %: %',sqlstate,expected,sqlerrm;end if;end;raise exception 'Expected rejection: %',command;end$$;
select pg_temp.assert_true(not has_function_privilege('anon','public.load_operational_state_v2()','EXECUTE'),'anonymous read blocked');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.save_operational_state(jsonb,text)','EXECUTE'),'legacy overwrite blocked');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.operational_state','UPDATE'),'direct overwrite blocked');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.operational_state','SELECT'),'raw capital read blocked');
begin;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select pg_temp.assert_error('select public.load_operational_state_v2()','42501');
select pg_temp.assert_error($q$select public.delete_catalog_product('fixture-product')$q$,'42501');
select pg_temp.assert_error($q$select public.save_storefront_settings('{"version":1}')$q$,'P0001');
select pg_temp.assert_error($q$select public.save_image_asset('fake','fake',1,'[{}]')$q$,'P0001');
select pg_temp.assert_error($q$select public.manage_store_order('fake','cancel','{}','Fixture reason')$q$,'P0001');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select pg_temp.assert_true(jsonb_array_length(public.load_operational_state_v2()->'data'->'capitalEntries')=0,'cashier cannot read capital');
select public.save_operational_state_v2(public.load_operational_state_v2()->'data',public.load_operational_state_v2()->>'updated_at');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select pg_temp.assert_true(jsonb_array_length(public.load_operational_state_v2()->'data'->'capitalEntries')=1,'cashier save preserves hidden capital');
select pg_temp.assert_error($q$select public.save_operational_state_v2(public.load_operational_state_v2()->'data',null)$q$,'40001');
select pg_temp.assert_error($q$select public.save_operational_state_v2(public.load_operational_state_v2()->'data','2000-01-01')$q$,'40001');
select pg_temp.assert_error($q$select public.save_operational_state_v2(jsonb_set(public.load_operational_state_v2()->'data','{capitalEntries}','[]'),public.load_operational_state_v2()->>'updated_at')$q$,'22023');
select pg_temp.assert_error($q$select public.save_operational_state_v2((public.load_operational_state_v2()->'data')-'expenses',public.load_operational_state_v2()->>'updated_at')$q$,'22023');
select pg_temp.assert_error($q$select public.save_operational_state_v2(jsonb_set(public.load_operational_state_v2()->'data','{sales,0,total}','1'),public.load_operational_state_v2()->>'updated_at')$q$,'42501');
-- A stale catalog revision must roll back the business operation as well.
select pg_temp.assert_error($q$select public.save_operational_state_v2(jsonb_set(public.load_operational_state_v2()->'data','{products,0,cloudUpdatedAt}','"2000-01-01"'),public.load_operational_state_v2()->>'updated_at',array['fixture-product'])$q$,'40001');
select pg_temp.assert_error($q$select public.save_operational_state_v2(jsonb_set(public.load_operational_state_v2()->'data','{products}',(public.load_operational_state_v2()->'data'->'products') || '[{"id":"duplicate","name":"Duplicate","publishable":false,"variants":[{"id":"duplicate-var","sku":"FIXTURE-1","stock":1,"price":1,"cost":1}]}]'),public.load_operational_state_v2()->>'updated_at',array['duplicate'])$q$,'23505');
select public.save_operational_state_v2(jsonb_set(public.load_operational_state_v2()->'data','{products,0,variants,0,stock}','9'),public.load_operational_state_v2()->>'updated_at',array['fixture-product']);
select pg_temp.assert_true(public.load_operational_state_v2()->'data'->'products'->0->'variants'->0->>'stock'='9','atomic stock saved');
rollback;
select pg_temp.assert_true((select count(*) from app_private.business_history)=0,'test rollback retained original history');
select pg_temp.assert_true((select count(*) from public.public_catalog_products)=1,'duplicate product rejected atomically');
select pg_temp.assert_true(not (app_private.public_order_result('{"id":"fixture","customerEmail":"private@example.invalid","payments":[{"amount":1}],"lines":[{"unitCost":25,"unitPrice":100}]}') ? 'customerEmail'),'public checkout omits private data');
select pg_temp.assert_true(not (app_private.public_order_result('{"lines":[{"unitCost":25}]}')->'lines'->0 ? 'unitCost'),'public checkout omits cost');
select pg_temp.assert_true(not has_function_privilege('authenticated','public.claim_store_email_batch(integer)','EXECUTE'),'email batch is service-only');
insert into public.store_orders(id,customer_email,data) values('email-order','fixture@example.invalid','{}');
insert into public.store_email_queue(id,order_id,recipient,kind,data,created_at) values('old-email','email-order','fixture@example.invalid','fixture','{}',now()-interval '100 days'),('fresh-email-a','email-order','fixture@example.invalid','fixture','{}',now()),('fresh-email-b','email-order','fixture@example.invalid','fixture','{}',now());
set role service_role;
select pg_temp.assert_true((select count(*) from public.claim_store_email_batch(1))=1,'claim first message');
select pg_temp.assert_true((select count(*) from public.claim_store_email_batch(1))=1,'claim different second message');
reset role;
select pg_temp.assert_true((select status from public.store_email_queue where id='old-email')='requiere_revision','stale email preserved for review');
select pg_temp.assert_true((select count(*) from public.store_email_queue where status='procesando')=2,'no duplicate claims');
